node --test test/ 2>&1 | tail -12; node --input-type=module -e "
import { handle } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
const c = (b) => handle({ method: 'POST', path: '/reminders', body: b });
// 1. timezone double-shift
const ist = c({ userId: 'u1', text: 'ist', at: '2026-03-01T09:00', tzOffsetMin: 330 }).body;
const ny  = c({ userId: 'u1', text: 'ny',  at: '2026-03-01T09:00', tzOffsetMin: -300 }).body;
console.log('IST stored due', new Date(ist.due_ms).toISOString(), '(correct 03:30Z)');
for (const t of ['2026-02-28T22:00:00Z','2026-03-01T03:30:00Z']) console.log('IST due at', t, dueReminders([ist], Date.parse(t)).length);
for (const t of ['2026-03-01T14:00:00Z','2026-03-01T19:00:00Z']) console.log('NY  due at', t, dueReminders([ny], Date.parse(t)).length);
// 2. bad at
for (const at of ['2026-03-01T09:00:00','tomorrow','2026-03-01']) { const r = c({ userId: 'u1', text: 'x', at }); console.log('at=',at,'->',r.status,'due_ms',r.body.due_ms, 'ever due?', dueReminders([r.body], 9e15).length); }
const r = c({ userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 'abc' }); console.log('tz=abc ->', r.status, r.body.due_ms);
// 3. missing query
try { handle({ method: 'GET', path: '/reminders' }); } catch (e) { console.log('GET no query ->', e.constructor.name, e.message); }
// 4. injection: SQL actually built
handle({ method: 'GET', path: '/reminders/search', query: { userId: \"x' OR '1'='1\", q: 'a' } }).status;
" 2>&1; node --input-type=module -e "
import { handle } from './src/api.js'; import { queryLog } from './src/db.js';
try { handle({ method: 'GET', path: '/reminders/search', query: { userId: \"x' OR '1'='1' --\", q: '' } }); } catch (e) { console.log('fake db:', e.message); }
console.log('SQL sent:', queryLog.at(-1).sql);
handle({ method: 'POST', path: '/reminders', body: { userId: 'victim', text: 's', at: '2026-03-01T09:00' } });
console.log('DELETE by other caller ->', handle({ method: 'DELETE', path: '/reminders/1' }).status);
"
